function isPerfect(n) {
  var sum = 0;
  for (var d = 1; d < n; d++) {
    if (n % d === 0) {
      sum += d;
    }
  }
  return sum === n;
}

var found = [];
for (var n = 2; n <= 30; n++) {
  if (isPerfect(n)) {
    found.push(n);
  }
}
console.log(found);
